/bin/bash -lc "python3 - <<'PY'
import zipfile, xml.etree.ElementTree as ET, re
p='/home/user/exam/grades.xlsx'
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
with zipfile.ZipFile(p) as z:
    sheet=ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    strings=[]
    sroot=ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in sroot.findall('m:si', ns):
        strings.append(''.join(t.text or '' for t in si.findall('.//m:t', ns)))

def v(c):
    val=c.find('m:v', ns)
    if val is None:
        return ''
    return strings[int(val.text)] if c.attrib.get('t')=='s' else val.text
for row in sheet.find('m:sheetData', ns).findall('m:row', ns):
    r=int(row.attrib['r'])
    if 2 <= r <= 11:
        cells={c.attrib['r']: v(c) for c in row.findall('m:c', ns)}
        vals=[cells.get(f'{col}{r}','') for col in list('ABCDEFGHIJKLM')]
        print(vals)
PY"

